import{_ as s,o as a,c as n,a2 as i}from"./chunks/framework.B4hAkGey.js";const k=JSON.parse('{"title":"6.2 进阶应用：5G 切片与 QoS 保障","description":"","frontmatter":{},"headers":[],"relativePath":"guide/06-5g-adaptation/advanced.md","filePath":"guide/06-5g-adaptation/advanced.md","lastUpdated":1792683941000}'),e={name:"guide/06-5g-adaptation/advanced.md"};function d(r,t,p,l,h,o){return a(),n("div",null,[...t[0]||(t[0]=[i(`<h1 id="_6-2-进阶应用-5g-切片与-qos-保障" tabindex="-1">6.2 进阶应用：5G 切片与 QoS 保障 <a class="header-anchor" href="#_6-2-进阶应用-5g-切片与-qos-保障" aria-label="Permalink to &quot;6.2 进阶应用：5G 切片与 QoS 保障&quot;">​</a></h1><blockquote><p>深入 5G QoS 机制、QFI 映射、WebRTC 带宽估计与 5G 网络的联动。</p></blockquote><hr><h2 id="_6-2-1-5g-qos-模型" tabindex="-1">6.2.1 5G QoS 模型 <a class="header-anchor" href="#_6-2-1-5g-qos-模型" aria-label="Permalink to &quot;6.2.1 5G QoS 模型&quot;">​</a></h2><p>5G 定义了更灵活的 QoS 体系：</p><table tabindex="0"><thead><tr><th>3GPP 标准</th><th>含义</th><th>WebRTC 映射</th></tr></thead><tbody><tr><td><strong>5QI</strong>（5G QoS Identifier）</td><td>标准化 QoS 等级</td><td>WebRTC 音视频 → 5QI=37（实时，GBR）</td></tr><tr><td><strong>QFI</strong>（QoS Flow Identifier）</td><td>每个 QoS 流的标识</td><td>WebRTC 可以携带 QFI 请求</td></tr><tr><td><strong>GBR</strong> / <strong>Non-GBR</strong></td><td>保证比特率 vs 尽力而为</td><td>WebRTC 音视频走 GBR，信令走 Non-GBR</td></tr><tr><td><strong>ARP</strong>（Allocation and Retention Priority）</td><td>资源抢占优先级</td><td>WebRTC 直播设高 ARP</td></tr></tbody></table><hr><h2 id="_6-2-2-5g-切片接入点" tabindex="-1">6.2.2 5G 切片接入点 <a class="header-anchor" href="#_6-2-2-5g-切片接入点" aria-label="Permalink to &quot;6.2.2 5G 切片接入点&quot;">​</a></h2><p>WebRTC 应用请求专用切片的三种方式：</p><table tabindex="0"><thead><tr><th>方式</th><th>适用场景</th><th>实现复杂度</th></tr></thead><tbody><tr><td><strong>网络运营商标配切片</strong></td><td>与运营商合作的大型直播平台</td><td>高（需企业合作）</td></tr><tr><td><strong>App 直接请求</strong></td><td>支持 5G Network Exposure Function 的网络</td><td>中（3GPP 正在标准化）</td></tr><tr><td><strong>默认切片优化</strong></td><td>普通消费者应用</td><td>低（依赖 WebRTC 自身优化）</td></tr></tbody></table><blockquote><p>目前大部分消费级 WebRTC 应用走&quot;默认切片优化&quot;——通过 WebRTC 自身的拥塞控制、带宽估计、FEC 来适应 5G。切片主要由运营商侧配置。</p></blockquote><hr><h2 id="_6-2-3-webrtc-gcc-拥塞控制-×-5g" tabindex="-1">6.2.3 WebRTC GCC 拥塞控制 × 5G <a class="header-anchor" href="#_6-2-3-webrtc-gcc-拥塞控制-×-5g" aria-label="Permalink to &quot;6.2.3 WebRTC GCC 拥塞控制 × 5G&quot;">​</a></h2><p>WebRTC 默认用 <strong>GCC（Google Congestion Control）</strong> 做带宽估计和拥塞控制。5G 下 GCC 的表现：</p><table tabindex="0"><thead><tr><th>5G 特性</th><th>对 GCC 的影响</th></tr></thead><tbody><tr><td>低时延</td><td>GCC 反馈更快，带宽估计更准</td></tr><tr><td>高带宽</td><td>GCC 不会过早降码率，充分利用 eMBB</td></tr><tr><td>网络切片</td><td>GCC 检测到丢包减少，维持高质量</td></tr><tr><td>MEC SFU</td><td>RTT 减小，GCC 收敛更快</td></tr></tbody></table><p>5G 下 GCC 默认参数可以调高：</p><div class="language-js vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">js</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// 通过 RTCRtpSender 的 setParameters 调整</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">const</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> params</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> sender.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">getParameters</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">()</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">params.encodings[</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">0</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">].minBitrate </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 800_000</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">   // 5G 下保底 800kbps</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">params.encodings[</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">0</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">].maxBitrate </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 4_000_000</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"> // 5G 下上限 4Mbps</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">await</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> sender.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">setParameters</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(params)</span></span></code></pre></div><hr><h2 id="_6-2-4-5g-mec-部署实践" tabindex="-1">6.2.4 5G MEC 部署实践 <a class="header-anchor" href="#_6-2-4-5g-mec-部署实践" aria-label="Permalink to &quot;6.2.4 5G MEC 部署实践&quot;">​</a></h2><p><strong>推荐架构</strong>：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>┌────────────────────────────────────────────────────────┐</span></span>
<span class="line"><span>│  5G 核心网                                              │</span></span>
<span class="line"><span>│                                                         │</span></span>
<span class="line"><span>│  中心机房                                        边缘机房（MEC）                        │</span></span>
<span class="line"><span>│  ┌──────────┐                                    ┌──────────────┐                      │</span></span>
<span class="line"><span>│  │ Redis    │                                    │ SFU 集群     │                      │</span></span>
<span class="line"><span>│  │ 信令中心 │                                    │ Mediasoup xN │                      │</span></span>
<span class="line"><span>│  │ 鉴权     │                                    │              │                      │</span></span>
<span class="line"><span>│  └────┬─────┘                                    └──────┬───────┘                      │</span></span>
<span class="line"><span>│       │骨干网（10~20ms）                                  │本地/区域                   │</span></span>
<span class="line"><span>│  ┌────┴─────┐                                    ┌──────┴───────┐                      │</span></span>
<span class="line"><span>│  │ CDN      │                                    │ 5G 基站集群  │                      │</span></span>
<span class="line"><span>│  │ 传统HLS  │                                    │ (gNodeB)     │                      │</span></span>
<span class="line"><span>│  └──────────┘                                    └──────────────┘                      │</span></span>
<span class="line"><span>└────────────────────────────────────────────────────────┘</span></span></code></pre></div><p>边缘节点部署要点：</p><ul><li>SFU 和 TURN 部署在<strong>同机房</strong>，Relayed 候选延迟降到最低</li><li>边缘节点做<strong>热备</strong>，故障时自动切换到中心机房 SFU</li><li>Redis 集群跨区域同步信令状态</li></ul><hr><h2 id="_6-2-5-5g-也有坑" tabindex="-1">6.2.5 5G 也有坑 <a class="header-anchor" href="#_6-2-5-5g-也有坑" aria-label="Permalink to &quot;6.2.5 5G 也有坑&quot;">​</a></h2><table tabindex="0"><thead><tr><th>坑</th><th>说明</th><th>应对</th></tr></thead><tbody><tr><td><strong>IPv6-only 网络</strong></td><td>部分 5G 运营商只分配 IPv6</td><td>STUN/TURN 必须支持 IPv6</td></tr><tr><td><strong>网络抖动</strong></td><td>高速移动下空口抖动加大</td><td>增大 jitter buffer、启用 FEC</td></tr><tr><td><strong>电量消耗</strong></td><td>5G 芯片组耗电是 4G 的 1.5~2×</td><td>移动端降码率、GPU 硬编、屏幕关闭时停推</td></tr><tr><td><strong>切片发现</strong></td><td>客户端不知道有哪些切片可用</td><td>等 3GPP 标准（Rel-18+），目前运营商标配</td></tr><tr><td><strong>5G/4G 切换</strong></td><td>移动中从 5G 掉到 4G</td><td>ICE 自动重收集，GCC 自动降码率</td></tr></tbody></table><hr><h2 id="下一节" tabindex="-1">下一节 <a class="header-anchor" href="#下一节" aria-label="Permalink to &quot;下一节&quot;">​</a></h2><p>→ <a href="./practice">6.3 实战案例：5G 低时延直播链路调优</a></p>`,29)])])}const c=s(e,[["render",d]]);export{k as __pageData,c as default};
